$uid = intval(FaBIdentityFromMZ($mzID)['object']->UniqueID);
DoDrawCard($player, 1);
$found = FaBFindUID($uid);
if ($found !== null && $found['zone'] === 'Arsenal') {
    $lessons = intval(FaBObjectCounters($found['object'])['LESSONS'] ?? 0) + 1;
    FaBSetObjectCounter($found['object'], 'LESSONS', $lessons);
    if ($lessons >= 3) {
        FaBMoveUID($uid, 'Banish', $player);
        $targets = FaBStageSearch($player, ['specialization'=>true]);
        if ($targets !== '') {
            $chosen = await $player.MZChoose($targets, "Find_a_specialization_for_arsenal");
            $card = FaBMoveChoice($player, $chosen, 'Temp', 'Arsenal');
            if ($card !== null) {
                $card->FaceDown = 0;
                FaBRevealChoices($player, FaBFindUID(intval($card->UniqueID))['mzID']);
            }
        }
        FaBFinishSearch($player);
    }
}
